function observe(id, name, studyId, statement, limitations = []) { return observation({ id, name, studyId, statement, limitations }); }
function evidence(...ids) { return ids.map((id) => ({ nodeId: `soc:${id}`, claimIds: [`C-soc-${id}`] })); }
function bibliographic(sourceId, reason = "Metadata identifies the original intellectual reference; unread chapters or theory are not experimental support.") { return { sourceId, locator: metadata, disposition: "metadata-only", reason }; }
const C = (id) => `C-soc-${id}`;

study({ id: "chase2002-rank-reassembly", sourceId: "chase2002-hierarchies", system: "Weight-matched female Metriaclima zebra in repeated four-fish laboratory groups",
  preparation: "Isolate fish for two weeks, assemble 22 four-fish groups, score aggression after 24 hours, isolate the same individuals for two more weeks and reassemble them. A group relationship is scored after six consecutive unretaliated aggressive acts. Compare each individual's rank and the group's linearity across the two assemblies.", observable: "Aggression-defined rank transitions and linear versus non-linear group hierarchies", finding: "Most assemblies are linear, while many individuals change ranks between assemblies.", locators: [chaseLoc[0], chaseLoc[2]], limitations: ["Isolation is intended to reduce prior social effects; complete erasure of social memory is not directly demonstrated.", "The same individuals are reused; rank changes are not member-turnover persistence or replacement of participants."] });
observe("fish-rank-reassembly", "Recurrent linearity with changing individual ranks", "chase2002-rank-reassembly", "The same weight-matched female cichlids usually form linear hierarchies in repeated assemblies, yet only 27.3% of the 22 groups retain an identical rank ordering. Both persistent structural form and variable individual placement matter; rank is not a fixed intrinsic label.");
study({ id: "chase2002-social-protocol", sourceId: "chase2002-hierarchies", system: "Four- and five-fish cichlid hierarchy formation under two social protocols",
  preparation: "Compare isolated pairwise round-robin encounters with simultaneous group assembly after two weeks of isolation. Four- and five-fish cohorts are weight matched. Round-robin dominance uses 15 consecutive acts in small encounter tanks; assembled-group scoring uses six acts after 24 hours in a larger tank. Preserve group-size-specific cohorts and repeated encounter histories.", observable: "Proportion of aggression-defined hierarchies classified as linear", finding: "Group assemblies yield a higher proportion of linear hierarchies than isolated pairwise encounter protocols.", locators: [chaseLoc[1], chaseLoc[2]], limitations: ["This tests a composite social-access/encounter protocol, not a selective intervention on one network edge or a particular cognitive faculty."] });
observe("fish-social-protocol", "Pairwise versus assembled-group encounter preparation", "chase2002-social-protocol", "Social access is changed through isolated round-robin encounters versus simultaneous group assembly, with different timing, tanks and dominance criteria retained as part of each protocol.");
observe("fish-hierarchy-context", "Social context changes hierarchy linearity", "chase2002-social-protocol", "Assemblies of four and five cichlids yield substantially more linear hierarchies than the corresponding isolated pairwise protocols. Prior-attribute variation remains present, so this does not show that interaction alone is sufficient or identify the unique winner, loser or bystander pathway.");
operating({ source: "fish-social-protocol", target: "fish-hierarchy-context", studyId: "chase2002-social-protocol", assertion: "The tested composite encounter protocol changes the distribution of aggression-defined group structures.", bearer: "Existing weight-matched female cichlids in the two specified social-access preparations", input: "Pairwise round-robin versus simultaneous group assembly, including their different encounter and scoring procedures", observable: "Hierarchy linearity within each group-size cohort", limit: "No isolated social-topology coefficient, all-species necessity, minimum group threshold or irreducible group cause is established." });

study({ id: "carter2013-social-sharing", sourceId: "carter2013-bat-sharing", system: "Captive common vampire bats of mixed relatedness and established familiarity",
  preparation: "Fast one of 20 tested bats for 24 hours, return it to fed cage-mates and record two hours of behavior and mass change. Across 48 trial days over two years, score directed mouth-licking bouts, independent-day grooming and microsatellite relatedness. Compare dyadic transfer predictors and recurring network ties; preserve repeated bats and dyads.", observable: "Mouth-licking transfer proxy, mass gain, grooming and relatedness-associated sharing patterns", finding: "Past partner help predicts food donations more strongly than relatedness alone; dyadic patterns persist across separated observation windows.", locators: carterLoc, limitations: ["Fasting induces opportunities to share but no randomized manipulation of partner generosity or reciprocal punishment was performed."] });
observe("bat-partner-sharing", "Partner-specific sharing predictors", "carter2013-social-sharing", "In the captive mixed-relatedness preparation, food received from a partner predicts food donated to that partner, alongside grooming and donor-sex effects. This is an association in repeated dyads, not a randomized test of partner reciprocity or a human contract.");
observe("bat-sharing-persistence", "Sharing ties recur across days and months", "carter2013-social-sharing", "Sharing networks are more similar than the randomized comparison across eight-day and six-month separations. This supports bounded persistence of relationships within the tested colony, without demonstrating independence from all current members or survival after complete replacement.");
observe("bat-generalized-sharing-null", "No detected generalized sharing increase", "carter2013-social-sharing", "The reported within-round and previous-day comparisons find no significant general increase in donating after a bat has itself been fed. Exact absolute amounts given and received across trials are not significantly correlated; this is not strict short-term tit-for-tat matching or equivalence of every reciprocity account.");
observe("bat-harassment-boundary", "Donor initiation constrains harassment-only interpretation", "carter2013-social-sharing", "Donors initiate most classified non-maternal sharing bouts; recipient age/forearm size do not significantly predict donations. These outcomes constrain harassment as a sole explanation in this colony, without excluding every solicitation process or directly measuring reproductive benefit.");

study({ id: "aplin2015-diffusion", sourceId: "aplin2015-bird-traditions", system: "Wild great-tit foraging techniques across eight Wytham Woods subpopulations",
  preparation: "Train two resident males in each of five subpopulations to open one physical side of a food puzzle, retaining three untrained-demonstrator controls. Release demonstrators and log RFID visits and door-direction solutions over 20 exposure days. Both techniques remain available and equally rewarded; independently sampled feeder associations enter network-diffusion analyses.", observable: "Technique-specific solves, uptake latency, acquisition order and fitted network/conformity relationships", finding: "Seeded techniques spread and become locally biased traditions; controls have slower and lower uptake, with no consistent side bias.", locators: [aplinLoc[0], aplinLoc[2]], limitations: ["Sites are the relevant treatment units; tens of thousands of repeated solutions are not independent colony-level replications.", "Control subpopulations were clustered geographically, limiting a fully randomized treatment contrast."] });
observe("bird-demonstrator-input", "Seeded demonstrators versus untrained controls", "aplin2015-diffusion", "The experimental input introduces two resident demonstrators trained on blue/right or red/left food-puzzle opening, compared with pairs given no technique training; both opening directions then remain available.");
observe("bird-tradition-diffusion", "Technique-specific local tradition after seeding", "aplin2015-diffusion", "Local uptake is faster and greater in seeded areas, and solutions preferentially use the introduced physical technique; controls show no consistent side bias. This supports a preparation-bound effect of demonstrator seeding, with geographic control placement retained as a design limitation.");
observe("bird-conformity-inference", "Network and conformity interpretation of acquisition", "aplin2015-diffusion", "Observed associations and acquisition order favor the fitted social-transmission model; first techniques disproportionately match the locally common variant. Conformist copying is a source-supported statistical interpretation, rather than direct measurement of belief, sanctions or a uniquely identified learning algorithm.");
operating({ source: "bird-demonstrator-input", target: "bird-tradition-diffusion", studyId: "aplin2015-diffusion", assertion: "Introducing technique-trained demonstrators changes subsequent local puzzle-solving uptake and technique preference within the field preparation.", bearer: "Existing wild great tits visiting the supplied puzzle-box and food sites", input: "Resident demonstrators trained to one opening direction versus untrained-demonstrator controls", observable: "RFID-linked solve acquisition and physical door-direction bias over the observation window", limit: "Control geography, site dependence and shared food apparatus remain explicit; the effect supplies no universal cultural norm, neural mechanism or group minimum." });
study({ id: "aplin2015-persistence", sourceId: "aplin2015-bird-traditions", system: "Nine-month follow-up of two seeded great-tit sites and one control site",
  preparation: "Reinstall food puzzles for five days at T1, T3 and C1 after nine months without apparatus access and without training new demonstrators. Distinguish birds previously present or previously solving from new participants. Approximately 40% of each subpopulation were present in the previous year; retain limited surviving sites and a device failure affecting one site.", observable: "Reappearance, uptake speed and retained physical technique preference among prior and new participants", finding: "The two seeded populations retain the introduced physical technique and quickly recruit solvers despite partial population turnover.", locators: [aplinLoc[1], aplinLoc[2]], limitations: ["This follow-up shares histories and surviving birds with the original experiment. It is neither an independent replication nor complete replacement of all carriers."] });
observe("bird-tradition-retention", "Tradition retained through partial population turnover", "aplin2015-persistence", "After nine months, the two revisited seeded sites retain their earlier technique bias while both prior and inexperienced birds solve the reintroduced puzzle. Surviving trained/knowledgeable birds and a supplied reward remain available; memory and social transmission are compatible explanations, not proven member-independent persistence.");

study({ id: "greene2013-cue-outflow", sourceId: "greene2013-ant-cues", system: "Pogonomyrmex barbatus field-colony forager outflow under odor-mimic interventions",
  preparation: "Introduce alumina mimics bearing blank solvent treatment, seed-associated oleic acid, colony-matched forager hydrocarbons or both odor classes. Compare three-minute outgoing trail counts before and after addition, excluding an immediate transient decline and using the reported multiple-testing correction. Preserve within-colony repeated treatments and the two field seasons.", observable: "Change in outgoing forager counts per three-minute observation window", finding: "Combined odor treatment increases outflow; blank and each single-cue treatment show no significant pre/post increase.", locators: [greeneLoc[0], greeneLoc[1], greeneLoc[3]], limitations: ["Both cue-class identity and mimic handling are part of the preparation; the unresolved hydrocarbon-unit conflict prevents a calibrated dose-response or minimum-signal rule."] });
observe("ant-combined-cue-input", "Combined and isolated chemical-cue intervention", "greene2013-cue-outflow", "Field nests receive the same type of inert mimic with combined forager/seed-associated odor, isolated odor classes or blank treatment; outgoing traffic is measured after the immediate handling transient.");
observe("ant-combined-cue-outflow", "Combined odors increase measured foraging outflow", "greene2013-cue-outflow", "Combined forager and seed-associated odor mimics increase outgoing trail counts in the reported field assay. This is a task-specific response to the supplied combination, not proof of a universal colony computation or receptor-level chemical mechanism.");
observe("ant-single-cue-null", "Blank and isolated-cue increases are not detected", "greene2013-cue-outflow", "The blank, seed-odor-only and forager-odor-only treatments have no significant measured pre/post outflow increase. Finite nulls constrain the tested combination account without establishing exact zero effects, biochemical synergy or universally necessary cue classes.");
operating({ source: "ant-combined-cue-input", target: "ant-combined-cue-outflow", studyId: "greene2013-cue-outflow", assertion: "The tested combined-cue intervention changes outgoing forager traffic relative to its declared preparation and controls.", bearer: "Existing harvester-ant colonies during active field foraging", input: "Mimics bearing the combined colony-matched forager and seed-associated odors", observable: "Outgoing trail counts after the defined handling exclusion period", limit: "No calibrated universal dose, caste requirement, neural oscillation, pheromone-trail recruitment mechanism or colony-wide maintenance cause is inferred." });
study({ id: "greene2013-mimic-interaction", sourceId: "greene2013-ant-cues", system: "Two field-colony vestibules under blank and combined-odor mimic presentation",
  preparation: "Observe unobstructed trajectories beneath a transparent entrance ceiling before and after blank mimics, then at least an hour later combined-odor mimics. Score contacts within an antenna length and distinguish contacts with ants versus mimics. Twenty focal foragers per treatment/colony are sampled before or after; preserve the fixed blank-before-combination order.", observable: "Focal interaction rates with other ants, mimics and both combined", finding: "Combined mimics receive more contacts than blanks and partly replace ant-ant interactions; total ant-plus-mimic contact rate does not significantly change.", locators: [greeneLoc[2], greeneLoc[3]], limitations: ["The fixed order and small two-colony sample do not isolate every alternative to odor identity. An observed contact rate is not direct evidence of molecular receptor integration."] });
