study({ id: "pinter2013-seed-activation", sourceId: "pinter2013-ant-activation", system: "Three field harvester-ant colonies observed beneath modified nest-entrance ceilings",
  preparation: "Add seeds near a foraging trail and select low- and high-return-rate windows. Track unobstructed outgoing ants through the vestibule, score encounters and fit pooled changes in encounter frequency before each departure. Compare colonies and interaction classes while retaining that every focal ant eventually leaves the nest.", observable: "Incoming flow, encounter rate and fitted change-point timing before outgoing departures", finding: "Encounter rates rise near departure and vary with return rate; the proposed necessary activation threshold is not tested against non-departing ants.", locators: [pinterLoc[0], pinterLoc[1]], limitations: ["Selecting low/high windows after seed addition and conditioning analysis on departure do not isolate a selective encounter-rate intervention."] });
